// Independent protocol port; Apache-2.0 reference: keiyoushi/extensions-source
// dbf6c05d6a9520c60533f1626616263522bbe71a/src/zh/mh1234.
// No fetched JavaScript is executed. Signed image URLs are resolved afresh per content request.
var BASE = 'https://m.wmh1234.com';
function fail(message) { throw new Error('漫画1234：' + message); }
function siteUrl(url) {
  if (typeof url !== 'string' || !/^https:\/\/m\.wmh1234\.com\//.test(url)) fail('来源地址无效');
  return url;
}
function readerUrl(url, requestedUrl) {
  if (typeof url !== 'string' || /[\s\\]/.test(url)) fail('阅读跳转地址不受支持');
  // Dart IO/Dio may expose the relative HTTP Location as response.realUri.
  // Resolve only a root-relative path against the already-trusted request origin.
  // Network-path references remain unsupported; never prepend BASE to an authority.
  if (/^\/(?!\/)/.test(url) && requestedUrl) {
    var origin = /^(https:\/\/[^/]+)\//.exec(readerUrl(requestedUrl));
    url = origin[1] + url;
  }
  if (!/^https:\/\/(?:m\.wmh1234\.com\/|reader\.hqread\.cc\/r\/)/.test(url)) fail('阅读跳转地址不受支持');
  return url;
}
async function page(url) {
  readerUrl(url);
  var response = await triomi.fetch(url);
  if (response.status !== 200) fail('HTTP ' + response.status);
  var finalUrl = readerUrl(response.url || url, url);
  var html = response.body || '';
  if (/challenge-platform|cf-chl-|Just a moment|验证码|人机验证/.test(html)) fail('站点要求访问验证');
  return {html:html, url:finalUrl};
}
async function value(html, selector, attr) {
  var rows = await triomi.select(html, selector, {v:{selector:'.',attr:attr || 'text'}});
  return rows.length ? String(rows[0].v || '').trim() : '';
}
function mangaId(url) {
  var match = /^https:\/\/m\.wmh1234\.com\/comic\/([0-9]+)\.html$/.exec(url);
  if (!match) fail('漫画地址无效');
  return match[1];
}
async function listing(url, requestedPage) {
  var response = await page(siteUrl(url));
  var html = response.html;
  var current = Number(await value(html, '.pagination-wrapper .on'));
  // Server clamps out-of-range requests to the final page; stop rather than repeat it.
  if (requestedPage > 1 && current > 0 && current < requestedPage) return [];
  // Search has a second recommendation grid: never mix those cards into results.
  var scope = url.indexOf(BASE + '/search/') === 0 ? '.container.mt-lg .comic-grid' : '#comicGrid';
  var rows = await triomi.select(html, scope + ' .comic-card', {
    title:'.comic-card__title',
    url:{selector:'a.comic-card__link',attr:'href',absolute:true},
    coverUrl:{selector:'img.comic-card__image',attr:'data-src',absolute:true}
  }, response.url);
  if (!rows.length && !(await value(html, scope, 'outerHtml'))) fail('漫画列表结构已变化');
  var seen = {}, items = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i], id = mangaId(row.url || '');
    if (!row.title) fail('漫画标题缺失');
    if (seen[id]) continue;
    seen[id] = true;
    items.push({remoteId:id,type:'manga',title:row.title,url:row.url,coverUrl:row.coverUrl});
  }
  return items;
}
async function discover(url, pageNumber) {
  return listing(url, pageNumber || 1);
}
async function search(keyword, pageNumber) {
  var n = pageNumber || 1;
  if (!String(keyword || '').trim()) return listing(BASE + '/category/order/hits' + (n > 1 ? '/page/' + n : ''), n);
  return listing(BASE + '/search/' + encodeURIComponent(keyword) + (n > 1 ? '/page/' + n : ''), n);
}
async function detail(url) {
  var id = mangaId(url), response = await page(url), html = response.html;
  var title = await value(html, '#mintWorkTitle');
  if (!title) fail('漫画详情结构已变化');
  var info = await triomi.select(html, '.mint-work-info p', {text:{selector:'.'},status:'.mint-tag'});
  var author = info.length ? String(info[0].text || '').replace(/\s*著$/, '').trim() : '';
  var state = info.length > 1 ? info[1].status || '' : '';
  var genre = info.length > 1 ? String(info[1].text || '').replace(state, '').trim() : '';
  var cover = await triomi.select(html, '#mintWorkCover', {url:{selector:'.',attr:'src',absolute:true}}, url);
  var groups = await triomi.select(html, '.mint-chapter-grid', {html:{selector:'.',attr:'html'},label:{selector:'.',attr:'data-title'}});
  if (!groups.length) fail('章节目录结构已变化');
  var result = [], seen = {};
  for (var g = 0; g < groups.length; g++) {
    var links = await triomi.select(groups[g].html, 'a[href]', {title:{selector:'.'},url:{selector:'.',attr:'href',absolute:true}}, url);
    // Each public chapter group is newest-first; reverse within, never across groups.
    links.reverse();
    for (var i = 0; i < links.length; i++) {
      var link = links[i];
      if (/APP/i.test(link.title || '')) continue;
      var match = /^https:\/\/m\.wmh1234\.com\/comic\/([0-9]+)\/([0-9]+)\.html$/.exec(link.url || '');
      if (!match || match[1] !== id || !link.title) fail('章节地址或标题无效');
      if (seen[link.url]) continue;
      seen[link.url] = true;
      var number = /第\s*([0-9]+(?:\.[0-9]+)?)\s*[话話章回卷]/.exec(link.title);
      result.push({remoteId:match[2],title:link.title,url:link.url,number:number ? Number(number[1]) : null,volumeTitle:groups[g].label || (groups.length > 1 ? '章节 ' + (g + 1) : '章节')});
    }
  }
  if (!result.length) fail('没有可公开阅读的章节');
  return {item:{remoteId:id,type:'manga',title:title,url:url,coverUrl:cover.length ? cover[0].url : undefined,author:author,description:await value(html, '#mintIntroPanel > div'),tags:genre ? genre.split(/\s+/) : [],status:/完结|完結/.test(state) ? 'completed' : /连载|連載/.test(state) ? 'ongoing' : 'unknown'},chapters:result};
}
async function content(url) {
  if (!/^https:\/\/m\.wmh1234\.com\/comic\/[0-9]+\/[0-9]+\.html$/.test(url || '')) fail('章节地址无效');
  var response = await page(url);
  // Follow only a literal public location.replace redirect, never evaluate site code.
  var redirect = /(?:window\.)?location\.replace\s*\(\s*(["'])(https:\/\/[^"'\\\s]+)\1\s*\)/.exec(response.html);
  if (redirect) response = await page(readerUrl(redirect[2]));
  var rows = await triomi.select(response.html, 'img.reader-image', {lazy:{selector:'.',attr:'data-src',absolute:true},src:{selector:'.',attr:'src',absolute:true}}, response.url);
  if (!rows.length) fail('没有公开的章节图片；可能需要登录或站点结构已变化');
  var images = [];
  for (var i = 0; i < rows.length; i++) {
    var image = rows[i].lazy || rows[i].src || '';
    if (!/^https:\/\/[^/\s]+\//.test(image) || /placeholder\.svg(?:[?#]|$)/i.test(image)) fail('章节图片地址无效');
    images.push(image);
  }
  return {images:images};
}
